#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"; TARGET="$ROOT/addons/geodot"; EXTERNAL="${BRUR_GEODOT_ADDON:-$HOME/.local/share/brur/geodot}"
GPKG="${BRUR_GEODOT_GPKG:-$ROOT/sweden-brur.gpkg}"; FAR_CACHE="${BRUR_GEODOT_FAR_CACHE:-$ROOT/.cache/geodot-far-cache.json}"
verify_external_addon(){ local addon="$1"; [[ -f "$addon/geodot.gdextension" ]] || { printf 'GEODOT_SETUP=FAIL preinstalled GeoDot missing at %s; set BRUR_GEODOT_ADDON to the installed addon directory\n' "$addon" >&2; return 69; }; if [[ "$(uname -s)" == "Darwin" && -f "$addon/macos/libgeodot.dylib" ]] && command -v otool >/dev/null 2>&1; then local dependency dependency_name; dependency="$(otool -L "$addon/macos/libgeodot.dylib" | awk '/@loader_path\/libgdal\./ {print $1; exit}')"; if [[ -n "$dependency" ]]; then dependency_name="${dependency#@loader_path/}"; [[ -f "$addon/macos/$dependency_name" ]] || { printf 'GEODOT_SETUP=FAIL incomplete external GeoDot bundle: missing %s beside libgeodot.dylib\n' "$dependency_name" >&2; return 69; }; fi; fi; }
if [[ ! -f "$TARGET/geodot.gdextension" || -L "$TARGET" ]]; then verify_external_addon "$EXTERNAL"; mkdir -p "$ROOT/addons"; rm -f "$TARGET"; ln -s "$EXTERNAL" "$TARGET"; printf 'GEODOT_SETUP=EXTERNAL source=%s target=%s\n' "$EXTERNAL" "$TARGET"; else printf 'GEODOT_SETUP=READY target=%s\n' "$TARGET"; fi
if [[ ! -f "$GPKG" && -f "$HOME/Dropbox/Code/brur-world/sweden-brur.gpkg" ]]; then GPKG="$HOME/Dropbox/Code/brur-world/sweden-brur.gpkg"; fi
if [[ -f "$GPKG" ]]; then mkdir -p "$(dirname "$FAR_CACHE")"; if [[ ! -f "$FAR_CACHE" || "$GPKG" -nt "$FAR_CACHE" || "$ROOT/tools/build_geodot_far_cache.py" -nt "$FAR_CACHE" ]]; then python3 "$ROOT/tools/build_geodot_far_cache.py" "$GPKG" --output "$FAR_CACHE"; else printf 'GEODOT_FAR_CACHE=READY output=%s\n' "$FAR_CACHE"; fi; else printf 'GEODOT_FAR_CACHE=SKIP missing=%s\n' "$GPKG"; fi
